site/data/monthly-life.css:
/* ZhiShi · monthly life hub | all illustrations SVG/CSS, no photographs */
.calendar-left-column{min-width:0;display:flex;flex-direction:column;gap:18px}
.calendar-left-column .calendar-panel{width:100%;min-width:0}
.life-hub{min-width:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-content:start}
.life-card{position:relative;min-width:0;padding:20px 21px 19px;background:rgba(255,255,255,.94);border:1px solid var(--season-border,#e7e7df);border-radius:22px;box-shadow:0 8px 30px rgba(47,57,45,.035);overflow:hidden;transition:border-color .3s ease,background-color .3s ease}
.life-card--flowers{background:linear-gradient(135deg,color-mix(in srgb,var(--season-surface,#f6eed6) 60%,white),#fff 84%)}
.life-card--letter{background:linear-gradient(140deg,#fffdfa 5%,color-mix(in srgb,var(--season-surface,#f6eed6) 26%,white) 100%)}
.life-card::after{content:'';position:absolute;right:-35px;top:-42px;width:123px;height:123px;border-radius:50%;border:1px solid color-mix(in srgb,var(--season-accent,#ddc088) 28%,transparent);pointer-events:none}
.life-card-head{display:flex;align-items:start;justify-content:space-between;gap:10px;position:relative;z-index:1;margin-bottom:15px}
.life-kicker{font:700 10px/1.4 Arial,sans-serif;letter-spacing:1.6px;color:#9caeaf;margin-bottom:6px}
.life-card-title{margin:0;color:#344c52;font-family:'Noto Serif SC','Songti SC',serif;font-weight:700;font-size:19px;letter-spacing:.3px;line-height:1.4}
.life-card-sub{color:#96a5a1;font-size:11px;margin-top:6px;line-height:1.65}
.life-mini-button{position:relative;z-index:2;flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;gap:3px;border:1px solid var(--season-border,#e2e9e4);border-radius:10px;background:#fffdfb;padding:8px 10px;color:var(--season-deep,#62766b);font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;min-height:34px}
.life-mini-button:hover{border-color:var(--season-primary,#8eac9a);background:var(--season-surface,#f2f6ed)}
.life-list{display:flex;flex-direction:column;gap:9px;position:relative;z-index:1}
.life-flower-row{display:flex;gap:11px;align-items:center;padding:9px 10px;border:1px solid color-mix(in srgb,var(--season-border,#e6eadd) 90%,white);border-radius:13px;background:#fffdfbdc;min-width:0}
.life-botanical{width:45px;height:45px;border-radius:12px;flex:0 0 45px;display:grid;place-items:center;background:color-mix(in srgb,var(--season-surface,#f2eedc) 75%,white);color:var(--season-primary,#ae8b51)}
.life-botanical svg{width:32px;height:32px;display:block}
.life-flower-info{flex:1;min-width:0}.life-flower-name{font-size:13px;font-weight:730;color:#465f5b}.life-flower-desc{font-size:10px;color:#91a19e;margin-top:4px;white-space:normal;line-height:1.55}
.life-tag{display:inline-block;vertical-align:middle;margin-left:5px;padding:2px 5px;background:var(--season-surface,#f2efdf);border-radius:5px;color:var(--season-deep,#707c60);font-size:9px;font-weight:600}
.life-flower-action{border:0;background:transparent;color:#809b91;font-size:11px;cursor:pointer;white-space:nowrap;align-self:center;padding:5px 1px}
.life-flower-action:hover{text-decoration:underline;color:var(--season-deep,#566e62)}
.life-footnote{margin:12px 0 0;color:#9aa9a6;font-size:10px;line-height:1.6}
.life-empty{padding:15px 13px;border:1px dashed #dfe8e2;border-radius:12px;color:#8d9e97;background:#fdfefdfa;font-size:12px;line-height:1.75}
.life-row{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:11px 12px;background:#fff;border:1px solid #e9eeec;border-radius:12px;min-width:0}
.life-row-info{min-width:0;flex:1}.life-row-title{display:block;color:#425d5f;font-weight:730;font-size:12px;line-height:1.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.life-row-caption{display:block;color:#9caeaa;font-size:10px;margin-top:4px;line-height:1.45;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.life-days{flex:0 0 auto;min-width:48px;text-align:right;font-family:Arial,sans-serif;color:var(--season-deep,#778c73);font-size:20px;line-height:1;font-weight:760}.life-days small{font-size:10px;color:#a2ada7;margin-left:3px;font-weight:500}.life-days.past{font-size:11px;line-height:1.5;color:#99a8aa}
.life-action-strip{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px}
.life-text-button{background:none;border:0;color:#8da39a;cursor:pointer;font-size:11px;padding:4px 0;text-decoration:none}.life-text-button:hover{color:#3d7466;text-decoration:underline}
.life-wish-source{font-size:11px;color:#8ca5a3;text-decoration:none}.life-wish-source:hover{text-decoration:underline}
.life-status-tag{display:inline-block;padding:3px 6px;border-radius:5px;background:#eef3ee;color:#63837a;font-size:10px;white-space:nowrap}
.life-status-tag.past{background:#f4f1ed;color:#9d978a}
.life-wish-add{margin-left:7px!important;border-radius:7px!important;border:1px solid #d8e5df!important;padding:5px 8px!important;line-height:1.5!important;background:#f8fbfa!important;color:#5e8274!important;font-weight:690!important;font-size:11px!important;cursor:pointer!important}
.life-wish-add:hover{background:#edf5ef!important}
.life-wish-add.is-saved{background:#f2efe5!important;color:#a48a58!important;border-color:#e4d6b5!important}
.activity-mini .life-wish-add{font-size:10px!important;margin:0 3px!important;padding:4px 6px!important;flex-shrink:0}
.life-letter-row{display:flex;align-items:center;gap:11px;padding:11px 12px;background:#fff;min-width:0;border:1px solid #ece9df;border-radius:12px}
.life-letter-envelope{flex:0 0 35px;width:35px;height:35px;border-radius:10px;display:grid;place-items:center;background:color-mix(in srgb,var(--season-surface,#f5ecd7) 80%,white);color:#ab9064}
.life-letter-envelope svg{width:22px;height:22px}
.life-letter-info{flex:1;min-width:0}.life-letter-info strong{font-size:12px;color:#625c50;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.life-letter-info small{font-size:10px;color:#9e9b8f;display:block;margin-top:3px}
.life-letter-open{border:0;background:transparent;color:#997d4f;padding:5px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap}
.life-tools{grid-column:1/-1;display:flex;gap:12px;align-items:center;justify-content:space-between;padding:0 4px 3px;color:#9aaba6;font-size:10px;line-height:1.6}
.life-tools-group{display:flex;gap:10px;align-items:center;flex:0 0 auto}
.life-tools button{font-size:10px;color:#7e9892;background:none;padding:4px 0;border:0;cursor:pointer}
.life-tools button:hover{text-decoration:underline}
.life-form-dialog{border:0;padding:0;background:transparent;max-width:calc(100vw - 28px);width:440px;max-height:calc(100vh - 50px);overflow:visible;color:#435a58}
.life-form-dialog::backdrop{background:rgba(31,42,39,.42);backdrop-filter:blur(3px)}
.life-form-frame{position:relative;background:#fffdfa;border:1px solid #eadfca;border-radius:20px;padding:25px 25px 23px;box-shadow:0 22px 70px rgba(17,32,28,.18);max-height:calc(100vh - 50px);overflow:auto}
.life-form-frame h3{font-family:'Noto Serif SC','Songti SC',serif;font-size:22px;margin:0 0 7px;color:#395754}
.life-form-frame p{font-size:12px;color:#9aa8a4;margin:0 0 18px;line-height:1.8}
.life-form-frame label{display:block;margin:12px 0 6px;font-size:12px;color:#6b807a;font-weight:700}
.life-form-frame input[type=text],.life-form-frame input[type=date],.life-form-frame textarea{display:block;width:100%;border-radius:10px;border:1px solid #dce5de;background:#fff;padding:10px 12px;font:13px/1.55 inherit;color:#3e5953;outline-offset:2px;box-sizing:border-box}
.life-form-frame textarea{min-height:165px;resize:vertical;font-family:'Noto Sans SC',sans-serif}
.life-form-frame input:focus,.life-form-frame textarea:focus{outline:2px solid #bed4c5;border-color:#91b29e}
.life-form-frame .life-checkbox-label{display:flex;align-items:center;gap:8px;font-weight:500;margin-top:14px;cursor:pointer}
.life-dialog-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:22px}
.life-dialog-actions button{border:1px solid #dce6e1;background:#fff;border-radius:9px;padding:9px 15px;font-size:12px;cursor:pointer;color:#6a8279;font-weight:650}
.life-dialog-actions .life-primary{background:var(--season-deep,#5e7a67);color:white;border-color:var(--season-deep,#5e7a67)}
.life-dialog-close{position:absolute;right:20px;top:18px;color:#869b92;background:transparent;border:0;font-size:21px;cursor:pointer}
.life-letter-paper{white-space:pre-wrap;line-height:1.95;color:#4c5f59;padding:19px;background:#faf7ee;border:1px solid #e9ddc6;border-radius:12px;font-size:13px;max-height:45vh;overflow:auto}
.life-note{font-size:10px!important;line-height:1.7!important;color:#a29c8d!important;margin-top:13px!important}
@media(max-width:1180px){.life-card{padding:16px}.life-card-title{font-size:17px}.life-hub{gap:11px}.life-flower-row{padding:8px;gap:8px}.life-flower-action{font-size:10px}}
@media(max-width:680px){.calendar-left-column{gap:13px}.life-hub{gap:11px;grid-template-columns:1fr}.life-card{border-radius:16px;padding:17px}.life-card-title{font-size:18px}.life-tools{flex-wrap:wrap;gap:7px}.life-form-frame{padding:20px}.life-wish-add{padding:6px!important}}
@media(prefers-reduced-motion:reduce){.life-card{transition:none}}
.calendar-left-column .calendar-panel,.life-hub,.life-card,.life-form-frame{box-sizing:border-box}
.life-wish-add{font-family:inherit}

/* V2 · 桂花水彩生活手账 · rebuilt interactive cards from approved visual direction.
   All /data/life-art/*.webp assets are watercolor illustrations, not photographs. */
.calendar-left-column{gap:18px}
.life-hub{--life-ink:#31434a;--life-muted:#918f81;--life-paper:#fffdf7;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;gap:17px 18px;padding:0 0 4px}
.life-card{isolation:isolate;min-width:0;overflow:hidden;padding:24px 24px 20px;border:1px solid #e1d9c5;border-radius:31px 34px 30px 38px;box-shadow:0 15px 38px rgba(111,91,60,.045);background:linear-gradient(155deg,rgba(255,254,251,.97),rgba(251,249,240,.95));transition:box-shadow .3s ease,transform .25s ease,border-color .3s}
.life-card::after{display:none!important}
.life-card::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:.45;background:repeating-linear-gradient(117deg,transparent 0px,transparent 9px,#d6bf9413 10px,#d6bf9413 11px,transparent 12px),radial-gradient(ellipse at 98% -9%,#e4ca8940,transparent 48%)}
.life-card--flowers{min-height:395px;background:linear-gradient(133deg,#fffdf6 1%,color-mix(in srgb,var(--season-surface,#efe6d2) 29%,#fffdfa) 98%);border-top-left-radius:42px;border-bottom-right-radius:52px}
.life-card--days{min-height:390px;border-top-right-radius:52px;background:linear-gradient(160deg,#fffefa 1%,#fcfaf3 100%);margin-top:20px}
.life-card--wishes{min-height:350px;padding-top:29px;border-top-left-radius:52px;border-bottom-left-radius:29px;background:linear-gradient(155deg,#fffdf9,#fcfaf2);margin-top:-6px}
.life-card--letter{min-height:357px;margin-top:15px;border-top-right-radius:45px;background:linear-gradient(150deg,#fffdf9,#f9f4e8 96%)}
.life-card:hover{box-shadow:0 17px 43px rgba(111,91,60,.065)}
.life-card-head{gap:8px;margin-bottom:15px;position:relative;z-index:3;align-items:start}
.life-kicker{color:#9b9b8e;font-family:Georgia,'Times New Roman',serif;letter-spacing:2px;font-size:10px;font-weight:700;margin-bottom:9px}
.life-card-title{color:#243b43;font-family:'Songti SC','Noto Serif SC',serif;font-size:23px;font-weight:740;line-height:1.4;letter-spacing:.4px;display:flex;align-items:center;gap:8px}
.life-card-sub{color:#978f7f;font-family:'Songti SC','Noto Serif SC',serif;font-size:12px;line-height:1.7;margin-top:4px}
.life-seal{font:700 7px/1.15 'Songti SC',serif;display:inline-flex;flex-direction:column;align-items:center;justify-content:center;flex:0 0 auto;border:1px solid #b4664f;color:#b4664f;border-radius:2px;padding:2px 3px;transform:rotate(6deg);opacity:.78;vertical-align:middle;letter-spacing:0}
.life-mini-button{background:#fffdf7e0;border:1px solid #dcd4c0;border-radius:13px;color:#6f704e;min-height:34px;padding:8px 13px;font-family:inherit;font-size:11px;box-shadow:0 1px 1px #fff inset}
.life-mini-button:hover{background:#f5f0df;border-color:#c7b795}
.life-card--days .life-mini-button{background:#84906a;color:#fff;border-color:#84906a;border-radius:20px;padding:9px 13px}
.life-card--days .life-mini-button:hover{background:#687b58}
.life-card-art{position:absolute;pointer-events:none;z-index:0}
.life-card-art--flowers{top:-11px;right:-5px;width:57%;height:214px;background:url('/data/life-art/osmanthus-hero.webp') center / cover no-repeat;opacity:.81;-webkit-mask-image:radial-gradient(ellipse at 67% 35%,#000 32%,transparent 76%);mask-image:radial-gradient(ellipse at 67% 35%,#000 32%,transparent 76%)}
.life-card--flowers:not(.is-autumn) .life-card-art--flowers{opacity:.34;filter:saturate(.5)}
.life-card--flowers .life-card-head{min-height:88px}
.life-card--flowers .life-kicker,.life-card--flowers .life-card-title,.life-card--flowers .life-card-sub,.life-season-poem{position:relative;z-index:2}
.life-card--flowers .life-card-head>div{max-width:82%}
.life-season-poem{font:13px/1.8 'Songti SC','Noto Serif SC',serif;color:#878470;margin:5px 0 13px;max-width:70%;min-height:23px}
.life-flower-row{background:#ffffffb8;border:1px solid #e6decc;padding:8px 11px 8px 6px;border-radius:20px 26px 19px 25px;min-height:72px;align-items:center;box-shadow:0 3px 10px rgba(132,109,67,.018)}
.life-flower-picture{width:82px;height:66px;flex:0 0 82px;border-radius:16px;display:grid;place-items:center;overflow:hidden;background:#f8f5eb}
.life-flower-picture img{display:block;width:100%;height:100%;object-fit:cover;mix-blend-mode:multiply;filter:saturate(.94)}
.life-flower-picture--generic{white-space:pre-line;font:700 16px/1.35 'Songti SC',serif;letter-spacing:2px;color:#8f9b76;background:radial-gradient(ellipse at 58% 25%,#e4e7d5,transparent 65%),#faf7e8}
.life-flower-name{font:700 16px/1.4 'Songti SC','Noto Serif SC',serif;color:#304a4a}
.life-flower-desc{font-size:11px;margin-top:3px;color:#979180;line-height:1.5}
.life-flower-location{display:block;color:#aaa08c;font-size:10px;line-height:1.45;margin-top:2px}
.life-flower-action{font-size:11px;color:#998453;font-weight:700;margin-right:2px}
.life-footnote{font-size:10px;color:#a6a08e;line-height:1.7;margin:13px 0 0;position:relative;z-index:2}
.life-list{gap:8px;z-index:2}
.life-card--days .life-list{margin-top:16px}
.life-anniv-row{appearance:none;display:flex;align-items:center;gap:9px;width:100%;min-width:0;padding:8px 10px;border:1px solid #e8e2d7;background:#fffcf9d9;border-radius:22px 28px 18px 23px;text-align:left;cursor:pointer;color:inherit;transition:transform .18s,border-color .18s;min-height:86px}
.life-anniv-row:hover{transform:translateY(-1px);border-color:#c5b690}
.life-anniv-art{width:66px;height:63px;flex:0 0 66px;border-radius:17px;overflow:hidden;display:grid;place-items:center;background:#fffdf8}
.life-anniv-art img{width:100%;height:100%;display:block;object-fit:cover;mix-blend-mode:multiply}
.life-anniv-detail{min-width:0;flex:1;align-self:center}
.life-anniv-detail .life-row-title{font:700 14px/1.45 'Songti SC','Noto Serif SC',serif;color:#263c43}
.life-anniv-detail .life-row-caption{font-size:10px;color:#a09a8a}
.life-anniv-counter{flex:0 0 auto;min-width:93px;max-width:135px;display:flex;flex-direction:column;align-items:flex-start;padding:0 0 0 9px;border-left:1px solid #e9e3d8;gap:3px}
.life-mode-pill{display:inline-block;align-self:flex-start;font-size:10px;line-height:1.2;border-radius:30px;padding:4px 8px;background:#eed7d2;color:#9e635c;white-space:nowrap}
.life-mode-pill--countup{background:#dfe9e0;color:#667b69}
.life-mode-pill--anniversary{background:#f2e5c5;color:#a38138}
.life-anniv-number{font:700 14px/1.3 'Songti SC','Noto Serif SC',serif;color:#304045;white-space:nowrap}
.life-anniv-next{font:10px/1.35 inherit!important;color:#aba08c;white-space:normal!important}
.life-round-arrow{display:grid;place-items:center;flex:0 0 20px;height:20px;border-radius:50%;background:#eeeadd;color:#9c997e;font-size:15px}
.life-card--days .life-all-days{background:transparent;color:#92826d;padding:6px;border:0;align-self:start}
.life-city-art{position:absolute;left:0;top:0;width:44%;height:125px;background:url('/data/life-art/shanghai-watercolor.webp') left top / contain no-repeat;opacity:.61;pointer-events:none;-webkit-mask-image:linear-gradient(to right,#000 48%,transparent);mask-image:linear-gradient(to right,#000 48%,transparent)}
.life-card--wishes .life-card-head{min-height:113px}
.life-card--wishes .life-card-head>div{padding-left:21%;}
.life-card--wishes .life-kicker{font-size:9px;letter-spacing:1.4px}
.life-card--wishes .life-mini-button{margin-top:0}
.life-card--wishes .life-card-title{font-size:22px;white-space:nowrap}
.life-list--tickets{gap:9px}
.life-ticket{position:relative;display:flex;align-items:center;gap:10px;min-height:83px;padding:10px 26px 10px 9px;border:1px solid #e6cfc3;background:linear-gradient(117deg,#f5e9de,#fdf9f1);box-shadow:0 5px 15px #ab917718;clip-path:polygon(0 5%,3% 5%,3% 0,97% 0,97% 5%,100% 5%,100% 95%,97% 95%,97% 100%,3% 100%,3% 95%,0 95%)}
.life-ticket--0{transform:rotate(-.5deg)}
.life-ticket--1{background:linear-gradient(107deg,#e8eddf,#fbf9ef);border-color:#d7dac9;transform:rotate(.8deg)}
.life-ticket--2{background:linear-gradient(111deg,#e2ecf2,#f7faf8);border-color:#d2dee5;transform:rotate(-.8deg)}
.life-ticket-art{width:67px;height:66px;flex:0 0 67px;background-position:left bottom;background-size:cover;background-repeat:no-repeat;border:1px solid #d6d9c9;border-radius:2px;filter:saturate(.81)}
.life-ticket-body{min-width:0;flex:1;display:flex;flex-direction:column;gap:3px}
.life-ticket-kind{font-size:10px;color:#ac8966}
.life-ticket-body .life-row-title{font:700 13px/1.4 'Songti SC','Noto Serif SC',serif;white-space:normal;color:#2f464c;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.life-ticket-meta{font-size:10px;color:#918f89;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.life-ticket-actions{display:flex;flex-direction:column;gap:4px;align-items:center;justify-content:center}
.life-ticket-heart{border:0;background:transparent;color:#ae7668;font-size:19px;cursor:pointer}
.life-ticket-link{font-size:10px;color:#93856c;text-decoration:none;white-space:nowrap}
.life-ticket-link:hover{text-decoration:underline}
.life-card--wishes .life-empty{margin-top:3px;background:#fffefaad;line-height:1.8}
.life-card--letter .life-card-head{min-height:86px;margin-bottom:2px}
.life-letter-stage{position:relative;min-height:206px;display:flex;justify-content:flex-end;align-items:center}
.life-envelope-art{position:absolute;z-index:0;left:-20px;bottom:-4px;width:73%;height:195px;background:url('/data/life-art/envelope-watercolor.webp') left center / contain no-repeat;pointer-events:none;opacity:.9;-webkit-mask-image:radial-gradient(ellipse at 50% 58%,#000 30%,transparent 83%);mask-image:radial-gradient(ellipse at 50% 58%,#000 30%,transparent 83%)}
.life-list--letters{position:relative;z-index:2;display:flex;flex-direction:column;align-items:end;justify-content:center;width:60%;gap:8px;margin-top:25px}
.life-letter-stationery{padding:14px 11px;background:#fffdf9ec;border:1px solid #e5d8bd;box-shadow:0 4px 11px #a9926419;border-radius:3px 11px 3px 10px;display:flex;align-items:center;gap:8px;width:100%;min-width:0}
.life-letter-info{min-width:0;flex:1}
.life-letter-info strong{font:700 13px/1.5 'Songti SC',serif;color:#343d3b}
.life-letter-info small{font-size:10px;white-space:normal;line-height:1.6}
.life-letter-open{font-size:10px;white-space:nowrap;color:#aa9470}
.life-letter-open.is-open{color:#537e6a}
.life-list--letters .life-empty{background:#fffaf2d9;font-size:11px;border-color:#e7dbc5;padding:12px 9px}
.life-list--letters .life-mini-button{background:transparent;padding:4px 0;color:#968367;border:0}
.life-card--letter .life-footnote{position:relative;z-index:2}
.life-tools{font-family:'Songti SC','Noto Serif SC',serif;color:#aaa598;padding:4px 8px 12px}
.life-form-dialog{width:min(500px,calc(100vw - 26px))}
.life-form-frame{background:linear-gradient(160deg,#fffefa,#fbf7ef);border-color:#ded5c1;border-radius:26px;color:#4b5d56}
.life-form-frame h3{color:#30464a;font-size:23px}
.life-form-frame label{color:#6c7a65}
