.life-mode-option input{accent-color:#8a9871}
.life-mode-option span{display:flex;flex-direction:column;gap:3px;min-width:0}
.life-mode-option b{color:#506258;font-size:12px}
.life-mode-option small{font:10px/1.45 inherit;color:#a09e91;font-weight:400}
.life-form-frame .life-checkbox-label[hidden]{display:none}
.life-empty{background:#fffdfac4;border-color:#e5dfd1;color:#9b988c}
.life-empty .life-text-button{font-weight:700;color:#958263}
@media(min-width:1400px){.life-card{padding:25px 27px}.life-card-title{font-size:25px}.life-flower-picture{width:88px;flex-basis:88px}.life-card--flowers{min-height:410px}.life-card--days{min-height:405px}}
@media(max-width:1360px){.life-card{padding:18px 16px}.life-card-title{font-size:19px}.life-hub{gap:13px}.life-anniv-art{width:48px;height:52px;flex-basis:48px}.life-anniv-counter{min-width:72px;max-width:110px;padding-left:6px}.life-anniv-number{font-size:12px}.life-ticket-art{flex-basis:48px;width:48px;height:57px}.life-card--wishes .life-card-title{font-size:19px}.life-flower-picture{width:65px;flex-basis:65px}.life-flower-desc{font-size:10px}.life-flower-location{font-size:9px}.life-card-art--flowers{height:176px}}
