@media(max-width:780px){.life-hub{grid-template-columns:1fr;gap:15px}.life-card{margin-top:0!important;padding:22px 20px;border-radius:25px;min-height:auto}.life-card--flowers{min-height:365px}.life-card--days{min-height:250px}.life-card--wishes{min-height:300px}.life-card--letter{min-height:350px}.life-card-title{font-size:23px}.life-card--wishes .life-card-title{font-size:22px}.life-flower-picture{width:82px;flex-basis:82px}.life-anniv-art{width:60px;flex-basis:60px}.life-anniv-counter{min-width:90px;max-width:150px}.life-anniv-number{font-size:14px}.life-ticket-art{width:67px;flex-basis:67px;height:63px}.life-flower-location{font-size:10px}.life-city-art{opacity:.35}.life-card--wishes .life-card-head>div{padding-left:17%}.life-letter-stage{min-height:200px}}
@media(max-width:440px){.life-card{padding:20px 15px}.life-card-title{font-size:21px}.life-seal{font-size:6px}.life-card--wishes .life-card-head>div{padding-left:0}.life-city-art{opacity:.13}.life-anniv-row{gap:6px;padding:8px 7px}.life-anniv-art{flex-basis:44px;width:44px;height:48px}.life-anniv-detail .life-row-title{font-size:12px}.life-anniv-counter{min-width:80px;max-width:113px;padding-left:6px}.life-anniv-number{font-size:12px}.life-mode-pill{font-size:9px;padding:3px 6px}.life-round-arrow{display:none}.life-ticket-art{flex-basis:52px;width:52px;height:60px}.life-letter-stage{min-height:178px}.life-envelope-art{width:65%;height:170px}.life-list--letters{width:64%}.life-card-head{gap:5px}.life-mini-button{padding:7px 9px;font-size:10px}.life-card--days .life-mini-button{padding:8px 10px}}


/* V2 · Future-letter correspondence. Replies appear only inside opened letters. */
.life-letter-reading{width:100%}
.life-letter-reading .life-letter-caption{
 font:700 11px/1.5 'Songti SC','Noto Serif SC',serif;
 letter-spacing:1.4px;color:#829281;margin:22px 1px 9px
}
.life-letter-reading .life-letter-paper{
 max-height:none;overflow:visible;white-space:pre-wrap;overflow-wrap:anywhere;
 padding:22px 24px;line-height:2.05;background:#f9f7f0;
 border:1px solid #e8dfcc;border-radius:15px;color:#53645b;
 font-family:'Songti SC','Noto Serif SC','PingFang SC',serif;font-size:14px
}
.life-reply-section{margin-top:27px;padding-top:22px;border-top:1px solid #e5e7dd}
.life-reply-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 15px}
.life-reply-heading h4{font:700 18px/1.5 'Songti SC','Noto Serif SC',serif;letter-spacing:.45px;color:#3b514b;margin:0}
.life-reply-count{font-size:11px;color:#85978c;background:#edf1e9;padding:5px 9px;border-radius:100px;white-space:nowrap}
.life-reply-history{position:relative;display:grid;gap:14px;margin:4px 0 15px}
.life-reply-history:not(:has(.life-reply-empty)){padding-left:18px}
.life-reply-history:not(:has(.life-reply-empty))::before{
 content:'';position:absolute;left:4px;top:9px;bottom:11px;width:1px;background:#d9e1d7
}
.life-reply-empty{font-size:12px!important;line-height:1.9!important;color:#96a397!important;margin:0!important}
.life-reply-item{position:relative;border:1px solid #e6e8df;border-radius:13px;padding:15px 16px 13px;background:#fffefb}
.life-reply-item::before{content:'';position:absolute;left:-18px;top:20px;width:9px;height:9px;border-radius:50%;background:#91a692;border:2px solid #fffefa;box-shadow:0 0 0 1px #dbe4d8}
.life-reply-item-head{display:flex;align-items:start;justify-content:space-between;gap:12px;flex-wrap:wrap}
.life-reply-date{font-size:11px;font-weight:650;color:#708474;line-height:1.7}
.life-reply-tools{display:flex;gap:10px;flex:none}
.life-reply-tools button{background:none;border:0;color:#87968c;padding:0 1px;font-size:11px;cursor:pointer}
.life-reply-tools button:hover,.life-reply-tools button:focus-visible{color:#3e6551;text-decoration:underline}
.life-reply-body{margin:10px 0 0!important;font:13px/1.95 'PingFang SC','Noto Sans CJK SC',sans-serif!important;color:#516259!important;white-space:pre-wrap;overflow-wrap:anywhere}
.life-reply-start{
 display:flex;align-items:center;justify-content:center;gap:5px;width:100%;padding:13px 15px;
 border:1px dashed #bacbb9;border-radius:12px;background:#f5f8f2;color:#59775f;
 font-size:12px;font-weight:700;cursor:pointer
}
.life-reply-start:hover{background:#edf3e9;border-color:#96b097}
.life-reply-compose{
 background:#f8f9f4;border:1px solid #dfe8d9;border-radius:14px;
 padding:17px 18px 14px;margin-top:13px
}
.life-reply-compose[hidden],.life-reply-start[hidden]{display:none!important}
.life-form-frame .life-reply-compose label{
 margin:0 0 10px;font-size:12px;color:#58715f;font-weight:700
}
.life-form-frame .life-reply-input{
 width:100%;box-sizing:border-box;min-height:112px;resize:vertical;
 border-radius:10px;background:#fffefa;border:1px solid #dce5dc;
 color:#364d43;padding:12px 13px;line-height:1.8
}
.life-form-frame .life-reply-input:focus{outline:2px solid #98b3a2;outline-offset:1px}
.life-reply-hint{font-size:10px!important;color:#8e9c90!important;margin:7px 0 14px!important}
.life-reply-compose-actions{display:flex;gap:10px;justify-content:flex-end}
.life-reply-compose-actions button{
 padding:10px 15px;border-radius:9px;border:1px solid #d8e1d8;
 background:white;color:#718779;font-size:12px;font-weight:650;cursor:pointer
}
.life-reply-compose-actions .life-reply-submit{background:#6f866a;color:white;border-color:#6f866a}
.life-reply-compose-actions .life-reply-submit:hover{background:#526b52}
@media(max-width:640px){
 .life-letter-reading .life-letter-paper{padding:16px;font-size:13px}
 .life-reply-section{margin-top:21px;padding-top:19px}
 .life-reply-item{padding:12px}
 .life-reply-item-head{gap:7px}
 .life-reply-tools{gap:8px}
}

site/data/editorial-redesign.css:
/* 知时 · 一页四时 / whole-page editorial watercolor skin · 2026-10-15
   This stylesheet is intentionally a visual layer. It preserves the existing
   DOM structure, localStorage data, calendar dates, widgets and all handlers.
   All artwork references /data/life-art/*.webp are illustrated watercolors.
   Real event photography remains limited to the existing events surface. */
:root{
  --editorial-ink:#283c41;
  --editorial-muted:#8c938d;
  --editorial-line:#e9e6dc;
  --editorial-shadow:0 10px 34px rgba(104,91,64,.045);
  --editorial-paper:#fffefa;
  --editorial-gold:#b18b50;
  --editorial-olive:#7d8b70;
  --editorial-serif:'Songti SC','Noto Serif SC','Noto Serif CJK SC','STSong','SimSun',serif;
}
html{background:#fcfbf7}
body{
  background:radial-gradient(ellipse at 10% -10%,color-mix(in srgb,var(--season-surface,#f7f2e8) 24%,white) 0,transparent 42%),
  color-mix(in srgb,var(--season-bg,#f9f8f2) 30%,#fafaf7) !important;
  color:var(--editorial-ink);
  font-size:13px;
}
.page{max-width:1640px;padding:0 clamp(19px,3vw,49px) 48px}
/* Navigation: keep positions and click targets; no new functional regions. */
.topbar{height:87px;min-height:87px;margin:0 0 5px;position:relative;border-bottom:1px solid #eae8df !important;gap:15px}
.topbar::after{content:"";position:absolute;pointer-events:none;width:230px;height:74px;left:10px;top:0;opacity:.10;
 background:url('/data/life-art/osmanthus-sprig.webp') center 32% / contain no-repeat;z-index:0}
.topbar >*{position:relative;z-index:1}
.brand{gap:10px}
.watercolor-mark{width:45px!important;height:45px!important;overflow:hidden;border:1px solid #eee7d8!important;border-radius:13px!important;background:#faf5e8!important}
.watercolor-mark img{width:100%;height:100%;object-fit:cover}
.brand-words strong{font-family:var(--editorial-serif);font-size:25px;letter-spacing:3px;font-weight:700;color:var(--editorial-ink)}
.brand-words small{font:500 9px/1.4 Georgia,serif;letter-spacing:2.8px;color:#9da4a0}
.topcenter{background:#fffefbec;border:1px solid #eae7dd;padding:4px;border-radius:28px;box-shadow:0 2px 12px #9b8b7120;gap:2px}
.topcenter button{font-size:12px;font-weight:550;border-radius:22px;color:#777f7b;padding:9px 15px}
.topcenter button.active{background:color-mix(in srgb,var(--season-surface,#f3ead1) 72%,white)!important;color:var(--season-deep,#526853)!important;box-shadow:none!important}
.topcenter button:hover{background:#f7f5ed;color:#586c61}
.season-control,.personal-tools-btn,.city-tag,.circle-btn{background:#fffefa!important;border:1px solid #e6e7dd!important;color:#6b7872!important;box-shadow:none!important}
.personal-tools-btn{padding:8px 11px!important}
.circle-btn{width:36px;height:36px}
/* Daily poem and cultural fortune: one airy horizontal editorial strip. */
.daily-culture-band{
 position:relative;overflow:hidden;min-height:72px!important;
 padding:13px 20px!important;margin:13px 0 18px!important;
 background:linear-gradient(105deg,#fffefa 0%,#fffefa 68%,color-mix(in srgb,var(--season-surface,#faf3df) 33%,white) 100%);
 border:1px solid #ebe7db;border-radius:19px;box-shadow:var(--editorial-shadow);
}
.daily-culture-band::after{content:"";position:absolute;pointer-events:none;right:9px;top:-34px;width:125px;height:140px;opacity:.24;background:url('/data/life-art/osmanthus-sprig.webp') center / contain no-repeat}
.daily-culture-band>*{position:relative;z-index:1}
.daily-verse{gap:11px;color:var(--editorial-ink)}
.daily-verse .micro-dot{background:var(--season-primary)!important;box-shadow:0 0 0 5px color-mix(in srgb,var(--season-surface) 55%,white)!important}
.daily-verse-line{font-family:var(--editorial-serif);font-weight:650;font-size:19px;letter-spacing:1.2px;line-height:1.65;white-space:normal}
.daily-verse-source{font-family:var(--editorial-serif);font-size:11px;color:#9f9587;white-space:nowrap}
.today-fortune{padding:8px 13px;gap:11px;background:#fdfcf8ed;border:1px solid #eae5d8;border-radius:13px;box-shadow:none}
.fortune-today-caption{color:var(--editorial-ink);font-weight:680}
.fortune-today-metric{color:#87918a}
.fortune-today-metric b{color:#5e6a5c}
.fortune-today-tip{max-width:150px;color:#8b9187;border-left-color:#e7e4d9}
/* Preserve main split: left calendar + four monthly lifestyle modules / right vertical sidebar. */
.main-layout{grid-template-columns:minmax(0,1fr) minmax(332px,365px)!important;gap:16px!important;margin-top:0!important;align-items:start}
.calendar-left-column{gap:15px!important}
.calendar-left-column .calendar-panel{
 position:relative;isolation:isolate;overflow:hidden;
 background:linear-gradient(160deg,#fffefa 0%,#fffefa 76%,#fcfaf4 100%)!important;
 border:1px solid #e9e5d9!important;box-shadow:var(--editorial-shadow)!important;
 border-radius:22px!important;padding:27px 27px 19px!important
}
.calendar-left-column .calendar-panel::before{content:"";position:absolute;top:-54px;right:-43px;z-index:-1;width:208px;height:195px;pointer-events:none;opacity:.29;background:url('/data/life-art/osmanthus-hero.webp') center / contain no-repeat;mask-image:linear-gradient(135deg,transparent,black 18%,black 67%,transparent);-webkit-mask-image:linear-gradient(135deg,transparent,black 18%,black 67%,transparent)}
.panel-heading{align-items:center;margin-bottom:16px!important;position:relative;z-index:1}
.month-title h2{font-family:var(--editorial-serif)!important;font-size:34px!important;letter-spacing:1px;font-weight:650;color:var(--editorial-ink);line-height:1.25}
.month-title:before{color:#a4a18f!important;letter-spacing:1.6px!important;font-size:9px!important}
.month-title p{color:#9fa19a;font-family:Georgia,var(--editorial-serif);font-size:11px;letter-spacing:.5px}
.month-controllers{gap:6px}
.narrow-btn{min-width:37px;height:37px;background:#fffefa;border:1px solid #eae7df;color:#687c74;border-radius:10px}
.narrow-btn:hover{background:var(--season-surface);border-color:var(--season-accent)}
.today-btn{background:color-mix(in srgb,var(--season-surface) 60%,white)!important;color:var(--season-deep)!important}
.view-legend{gap:11px;padding:13px 0 13px!important;border-top:1px solid #f0eee7;color:#969f99;font-size:10px}
.legend-right{color:#abb1ab}
.state-strip-sample.rest{background:#b3cbd6!important}.state-strip-sample.work{background:#aacbbb!important}
.weekdays{padding:2px 0 11px}
.weekdays span{font-size:11px;font-weight:650;color:#8d9893}
.weekdays span:nth-child(6),.weekdays span:nth-child(7){color:#809bab}
.month-grid{gap:5px!important;grid-auto-rows:minmax(105px,auto)!important;overflow:visible;border:0!important;border-radius:0!important;background:transparent}
.day-cell{min-height:105px;border:1px solid #f0eee6!important;border-radius:11px!important;background:#fffefa!important;padding:9px 8px 14px!important;box-shadow:none!important;color:#42595d!important}
.day-cell:hover:not(.outside){border-color:color-mix(in srgb,var(--season-accent) 37%,#e6e8e0)!important;background:#fdfcf6!important}
.day-cell.selected,.day-cell.selected.rest-day{background:color-mix(in srgb,var(--season-surface) 59%,white)!important;border-color:var(--season-primary)!important;box-shadow:0 0 0 1px color-mix(in srgb,var(--season-primary) 55%,white)!important}
.day-cell.rest-day:not(.selected){background:#f1f6f8!important;border-color:#e4edf1!important}
.day-cell.makeup-work:not(.selected){background:#eff6f0!important;border-color:#e3eee5!important}
.day-cell.outside{background:#fbfbf8!important;opacity:.50}
.day-cell.rest-day::after,.day-cell.makeup-work::after{height:4px!important;left:10px!important;right:10px!important;bottom:5px!important;border-radius:4px!important}
.day-cell.rest-day::after{background:#adc7d4!important}.day-cell.makeup-work::after{background:#a7cbb4!important}
.day-cell.today .date-num{background:var(--season-deep)!important;color:white!important}
.date-num{font-family:Georgia,var(--editorial-serif);font-weight:650;font-size:16px;color:#314b55}
.day-cell.weekend .date-num,.day-cell.rest-day .date-num{color:#668a9c}
.date-badge.rest{background:#dfedf5;color:#6998ae}.date-badge.work{background:#dcefe1;color:#638f73}
.lunar-label{color:#a1a59c;font-size:10px}
.lunar-label.term{color:var(--editorial-gold)}
.cell-inspiration{font-size:9px;color:#879c8e;padding-top:4px!important}
.month-foot{border-top:1px solid #f0eee7;margin-top:12px;padding-top:13px!important;color:#9ca69c;font-size:10px}
.foot-link{color:var(--season-deep);font-size:10px}
/* The right column remains a vertical stack, with distinct light cards. */
.detail-panel.zh-sidebar{display:flex;flex-direction:column;gap:12px;padding:0;background:transparent;border:0;box-shadow:none}
.zh-sidebar>section,.zh-sidebar>details{
 border:1px solid #eae7de!important;border-radius:18px!important;
 box-shadow:var(--editorial-shadow)!important;background:#fffefa!important;
}
.zh-sidebar .side-overview{position:relative;isolation:isolate;overflow:hidden;padding:18px 17px 15px;grid-template-columns:minmax(0,1fr) 111px;min-height:156px}
.zh-sidebar .side-overview::before{content:"";pointer-events:none;position:absolute;z-index:-1;right:-8px;bottom:-17px;width:225px;height:110px;background:url('/data/life-art/shanghai-watercolor.webp') center / contain no-repeat;opacity:.24}
.zh-sidebar .side-label,.v7-eyebrow{font:700 10px/1.5 Georgia,serif;letter-spacing:1.7px;color:#999f99}
.zh-sidebar .side-date{font-family:var(--editorial-serif);font-size:22px;font-weight:650;color:var(--editorial-ink);margin-top:7px}
.zh-sidebar .side-lunar{color:#949c96;font-size:11px}
.zh-sidebar .weather-module{background:#f7f8f4ee;border:1px solid #e8e9df;border-radius:14px;color:#687f87;padding:7px 4px 9px}
.zh-sidebar .weather-temp{font-size:22px;color:#4b6973}
.zh-sidebar .weather-rain{color:#98a5a3;font-size:9px}
.zh-sidebar .weather-advice{border-top:1px solid #ecece4;color:#8c9b93;font-size:10px;line-height:1.6}
.zh-sidebar .inspiration-card.v7-joy-card{position:relative;isolation:isolate;background:linear-gradient(119deg,#fff9ed 0%,#fffdfa 70%)!important;border-color:#efe5d4!important;box-shadow:var(--editorial-shadow)!important;padding:20px 20px 17px!important}
.zh-sidebar .inspiration-card.v7-joy-card::after{content:""!important;position:absolute;pointer-events:none;right:-12px;top:-16px;width:136px;height:133px;opacity:.17;background:url('/data/life-art/osmanthus-sprig.webp') center / contain no-repeat;z-index:-1;font-size:0!important}
.v7-card-heading .v7-eyebrow{color:#af9b80}
.v7-label{color:#9a7a47;background:#f8efdc;padding:5px 9px}
.zh-sidebar .idea-scope{margin-top:14px;color:#8e927b;font-size:10px}
.zh-sidebar .inspiration-card h3{font:700 22px/1.45 var(--editorial-serif);letter-spacing:.1px;color:#3b4c46;margin:7px 0 7px}
.zh-sidebar .inspiration-card p{font-size:11px;line-height:1.72;color:#898b7e}
.zh-sidebar .inspiration-info{margin-top:11px;gap:6px}
.zh-sidebar .inspiration-info span{background:#f5efe4;border:1px solid #efe5d4;color:#927d5e;border-radius:7px;padding:5px 7px}
.zh-sidebar .inspiration-actions{margin-top:12px}
.zh-sidebar .pill-action{background:var(--season-deep)!important;border-radius:10px!important;font-size:11px;padding:9px 13px}
.zh-sidebar .small-arrow{color:#8b806c}
.also-try{margin-top:13px;padding-top:10px;border-top-color:#f0e8db}
.also-try-option{background:#fffdfa;border-color:#efe9de;border-radius:9px;padding:8px 10px}
.zh-sidebar .v7-memo-card,.zh-sidebar .side-activity-card{padding:18px!important}
.zh-sidebar .v7-section-head h4{font-family:var(--editorial-serif);font-size:17px;font-weight:700;color:#304448}
.v7-section-head button{border:1px solid #e7e8dd;background:var(--season-surface);color:var(--season-deep);border-radius:9px;padding:7px 10px}
.zh-sidebar .v7-memo-card #memoList{margin-top:10px}
.zh-sidebar .v7-memo-card .memo-row{padding:9px 0;border-bottom:1px solid #f0efe8}
.memo-text strong{color:#536a62;font-size:11px}
.memo-color{width:5px}
.memo-check{border-radius:6px}
.zh-sidebar .v7-memo-card .add-blank{background:#fffefa;border:1px dashed #dcded2;color:#76877a;padding:10px}
.zh-sidebar .side-activity-card{position:relative;overflow:hidden;isolation:isolate}
.zh-sidebar .side-activity-card::after{content:"";position:absolute;pointer-events:none;z-index:-1;right:-22px;top:1px;width:128px;height:70px;background:url('/data/life-art/shanghai-watercolor.webp') center / contain no-repeat;opacity:.14}
.activity-time-tip{font-size:10px;color:#a1a59c}
.activity-mini{border-top:1px solid #f0eee7;padding:10px 0}
.activity-icon{background:#f5f3ea;color:#8c987a;border-radius:10px}
.activity-body strong{font-size:11px;font-weight:660;color:#4b6265}
.activity-tag{color:#a38b62}
.activity-mini>a{color:#837951}
.activity-footnote{color:#a7aaa3;font-size:9px}
