/* Solar-theme visual bridge · V1.1 (restores all 24 thematic palettes)
 * The watercolor visual structure stays fixed; every theme paints its color
 * into only selected surfaces and accents. Calendar rest/work stays invariant.
 * Actual values come from /data/solar-term-themes.js via applySeasonTheme(). */
:root{
  --editorial-gold:color-mix(in srgb,var(--season-primary,#b18b50) 77%,#b18b50);
  --editorial-olive:var(--season-primary,#7d8b70);
  --editorial-active:var(--season-deep,#566a60);
  --editorial-tint:color-mix(in srgb,var(--season-surface,#f5f1e6) 54%,#fffefa);
  --editorial-wash:color-mix(in srgb,var(--season-surface,#f5f1e6) 24%,#fffefa);
  --editorial-soft-border:color-mix(in srgb,var(--season-accent,#d7cbaa) 38%,#eae7de);
}
html{
  background-color:var(--season-bg,#f9f8f2)!important;
  transition:background-color .45s ease;
}
body{
  background-color:var(--season-bg,#f9f8f2)!important;
  background-image:
    radial-gradient(ellipse at 3% 4%,color-mix(in srgb,var(--season-accent,#d7cbaa) 22%,transparent),transparent 43%),
    radial-gradient(ellipse at 93% 81%,color-mix(in srgb,var(--season-surface,#f5f1e6) 26%,transparent),transparent 48%)!important;
  transition:background-color .45s ease;
}
.topbar{
  border-bottom-color:var(--editorial-soft-border)!important;
}
.topcenter{
  border-color:var(--editorial-soft-border)!important;
}
.topcenter button.active{
  background:color-mix(in srgb,var(--season-surface,#f5f1e6) 86%,#fffefa)!important;
  color:var(--editorial-active)!important;
}
.topcenter button:not(.active):hover{
  background:var(--editorial-wash)!important;
}
.season-control{
  border-color:var(--season-border,#e5e5dc)!important;
  background:var(--editorial-wash)!important;
  color:var(--editorial-active)!important;
}
.season-control select,.season-control span{
  color:var(--editorial-active)!important;
}
.season-control:focus-within{
  outline:2px solid var(--season-primary,#9a9473);
  outline-offset:2px;
}
.city-tag{
  background:var(--editorial-wash)!important;
  border-color:var(--season-border,#e5e5dc)!important;
  color:var(--editorial-active)!important;
}
.daily-culture-band{
  background:linear-gradient(105deg,#fffefa 0%,var(--editorial-wash) 69%,var(--editorial-tint) 100%)!important;
  border-color:var(--editorial-soft-border)!important;
}
.today-fortune{
  background:var(--editorial-tint)!important;
  border-color:var(--season-border,#e5e5dc)!important;
}
.fortune-today-caption,.fortune-today-metric b{
  color:var(--editorial-active)!important;
}
.calendar-left-column .calendar-panel{
  background:linear-gradient(157deg,#fffefa 15%,var(--editorial-wash) 100%)!important;
  border-color:var(--editorial-soft-border)!important;
}
.month-title h2{
  color:var(--editorial-active)!important;
}
.today-btn{
  background:var(--editorial-tint)!important;
  border-color:var(--season-border,#e5e5dc)!important;
  color:var(--editorial-active)!important;
}
.narrow-btn:hover{
  background:var(--editorial-wash)!important;
}
.day-cell:hover:not(.outside):not(.selected){
  background:var(--editorial-wash)!important;
  border-color:var(--editorial-soft-border)!important;
}
.day-cell.selected,.day-cell.selected.rest-day,.day-cell.selected.makeup-work{
  background:color-mix(in srgb,var(--season-surface,#f5f1e6) 78%,white)!important;
  border-color:var(--season-primary,#96816c)!important;
  box-shadow:0 0 0 1px color-mix(in srgb,var(--season-primary,#96816c) 65%,white)!important;
}
.day-cell.today .date-num{
  background:var(--editorial-active)!important;
  color:white!important;
}
.lunar-label.term{
  color:var(--editorial-gold)!important;
}
.zh-sidebar>section,.zh-sidebar>details{
  border-color:var(--editorial-soft-border)!important;
}
.zh-sidebar .weather-module{
  background:var(--editorial-tint)!important;
  border-color:var(--season-border,#e5e5dc)!important;
}
.zh-sidebar .inspiration-card.v7-joy-card{
  background:linear-gradient(135deg,color-mix(in srgb,var(--season-surface,#f5f1e6) 74%,white),var(--editorial-wash) 91%)!important;
  border-color:var(--season-border,#e5e5dc)!important;
}
.zh-sidebar .inspiration-card h3{
  color:var(--editorial-active)!important;
}
.v7-label,.zh-sidebar .inspiration-info span{
  background:color-mix(in srgb,var(--season-surface,#f5f1e6) 71%,white)!important;
  border-color:var(--season-border,#e5e5dc)!important;
  color:var(--editorial-active)!important;
}
.zh-sidebar .pill-action{
  background:var(--editorial-active)!important;
}
.v7-section-head button{
  background:var(--editorial-tint)!important;
  border-color:var(--season-border,#e5e5dc)!important;
  color:var(--editorial-active)!important;
}
.zh-sidebar .v7-memo-card .add-blank{
  border-color:var(--season-border,#e5e5dc)!important;
}
.zh-sidebar .fortune-card{
  border-color:var(--season-border,#e5e5dc)!important;
}
.expand-toggle{
  background:var(--editorial-tint)!important;
  color:var(--editorial-active)!important;
}
.life-card{
  background:linear-gradient(154deg,#fffefa 10%,var(--editorial-wash) 100%)!important;
  border-color:var(--editorial-soft-border)!important;
}
.life-card--flowers{
  background:linear-gradient(125deg,#fffefa 35%,var(--editorial-tint) 100%)!important;
}
.life-card--days,.life-card--wishes,.life-card--letter{
  background:linear-gradient(151deg,#fffefa 32%,var(--editorial-wash) 100%)!important;
}
.life-mini-button:hover{
  background:var(--editorial-tint)!important;
  color:var(--editorial-active)!important;
}
.life-mode-pill{
  border-color:var(--season-border,#e5e5dc);
}
.month-foot .foot-link{
  color:var(--editorial-active)!important;
}
@media(prefers-reduced-motion:reduce){
 html,body{transition:none!important}
}
/* Keep off-days, weekends, and make-up workdays consistently distinct
   across all 24 themes (do not theme their status backgrounds). */
.day-cell.rest-day:not(.selected){background:#f1f6f8!important;border-color:#e4edf1!important}
.day-cell.makeup-work:not(.selected){background:#eff6f0!important;border-color:#e3eee5!important}
.day-cell.rest-day::after{background:#adc7d4!important}
.day-cell.makeup-work::after{background:#a7cbb4!important}

